import React, { useState, useEffect, useRef } from 'react';
import { useAuth } from '../../context/AuthContext';
import { useMessage } from '../../context/MessageContext';
import { jobApi } from '../../api/api';
import '../../styles/RecommendationsPage.css';
import 'bootstrap-icons/font/bootstrap-icons.css'; // Keep this import for other potential uses, even if icons are removed here

function RecommendationsPage() {
  const { currentUser } = useAuth(); // Keep currentUser if you still need it for other logic
  const { setMessage, setLoading } = useMessage();
  const [recommendedJobs, setRecommendedJobs] = useState([]);
  const [selectedJob, setSelectedJob] = useState(null);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const menuRef = useRef();

  useEffect(() => {
    // Fetch all jobs when the component mounts
    fetchAllJobs();
  }, []); // Empty dependency array ensures it runs once on mount

  const fetchAllJobs = async () => { // Renamed function for clarity
    setLoading(true);
    try {
      // Assuming jobApi.getAllJobs() exists and returns all jobs
      // You might need to implement this method in your api.js
      const response = await jobApi.getAllJobs();
      setRecommendedJobs(response);
    } catch (error) {
      setMessage('Failed to fetch jobs: ' + error.message);
    } finally {
      setLoading(false);
    }
  };

  const openJobDetails = (job) => {
    setSelectedJob(job);
  };

  const closeJobDetails = () => {
    setSelectedJob(null);
  };

  // Handle outside click for radial menu
  useEffect(() => {
    const handleClickOutside = (e) => {
      if (menuRef.current && !menuRef.current.contains(e.target)) {
        setIsMenuOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  return (
    <div className="recommendations-wrapper">
      <div className="background"></div>
      <div className="header">
        {/* Removed the icon */}
        <h2 className="header-text">All Available Job Listings</h2> {/* Updated header text */}
      </div>

      <div className="recommendation-grid">
        {recommendedJobs.length > 0 ? (
          recommendedJobs.map((job, index) => {
            const matchScore = job.matchScore;
            // Kept matchScore display. If 'matchScore' is no longer relevant for 'all jobs',
            // you might want to remove this line or adjust its logic based on your backend data.
            const displayMatchScore =
              matchScore !== undefined ? `Match: ${(matchScore * 100).toFixed(0)}%` : null;

            return (
              <div key={index} className="job-card" onClick={() => openJobDetails(job)}>
                <h3>{job.title || 'Untitled Job'}</h3>
                <p><strong>Location:</strong> {job.location || 'Not specified'}</p>
                {displayMatchScore && <p className="match-score">{displayMatchScore}</p>}
                {/* Removed the info icon */}
                {/* job.description && (
                  <i
                    className="bi bi-info-circle-fill info-icon"
                    title="Click to view full job details"
                  ></i>
                )*/}
              </div>
            );
          })
        ) : (
          <p className="no-jobs-message">No jobs found. Please check back later or try refreshing.</p>
        )}
      </div>

      {selectedJob && (
        <div className="job-detail-overlay" onClick={closeJobDetails}>
          <div className="job-detail-card" onClick={(e) => e.stopPropagation()}>
            <h2>{selectedJob.title || 'Untitled Job'}</h2>
            <p>
              <strong>Description:</strong> {selectedJob.description || 'No description provided'}
            </p>
            <p>
              <strong>Skills:</strong> {selectedJob.skills?.length ? selectedJob.skills.join(', ') : 'Not specified'}
            </p>
            <p>
              <strong>Experience:</strong> {selectedJob.experience || 'Not specified'}
            </p>
            <p>
              <strong>Location:</strong> {selectedJob.location || 'Not specified'}
            </p>
            <p>
              Posted by: <span className="poster-username">{selectedJob?.posterUsername || 'Unknown'}</span>{' '}
              on{' '}
              {selectedJob?.postedDate
                ? new Date(selectedJob.postedDate).toLocaleDateString()
                : 'Unknown Date'}
            </p>
            <button onClick={closeJobDetails}>Close</button>
          </div>
        </div>
      )}

      {/* Radial Menu */}
      <div className="radialMenuWrapper">
        <button className="radialMenuBtn" onClick={() => setIsMenuOpen(!isMenuOpen)}>
          {/* Replaced icons with text for the button */}
          {isMenuOpen ? 'X' : '+'}
        </button>

        {isMenuOpen && (
          <div className="menuItems menuItemsActive" ref={menuRef}>
            <button onClick={fetchAllJobs} title="Refresh All Jobs"> {/* Changed refresh function */}
              {/* Replaced icon with text */}
              Refresh
            </button>
            {/* Add more buttons as needed */}
          </div>
        )}
      </div>
    </div>
  );
}

export default RecommendationsPage;
